<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api} from '../api'
const props=defineProps({course:Object,staff:Boolean})
const data=ref(null),sources=ref([]),sourceIndex=ref(''),selected=ref(null),form=ref(null),original=ref(''),busy=ref(false),error=ref(''),notice=ref(''),pdf=ref(null),preview=ref(null),reviewed=ref(false),anonymized=ref(false),authorized=ref(false),noLeak=ref(false),authorizationRef=ref('')
const base=`/courses/${props.course.id}/showcases`,writable=computed(()=>props.staff&&props.course.status!=='archived'),dirty=computed(()=>!!form.value&&JSON.stringify(form.value)!==original.value)
function guard(){return !dirty.value||confirm('觀摩草稿尚未儲存，確定離開？')}
onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
function unload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{load();window.addEventListener('beforeunload',unload)});onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
async function load(){try{data.value=await api(base);if(writable.value)sources.value=await api(base+'/sources')}catch(e){error.value=e.message}}
function resetReview(){preview.value=null;reviewed.value=false;anonymized.value=false;authorized.value=false;noLeak.value=false;authorizationRef.value=''}
function select(item){if(!guard())return;selected.value=item;resetReview();pdf.value=null;if(data.value.staff){form.value={title:item.content.title,background:item.content.background,answer:item.content.answer,notes:item.content.notes};original.value=JSON.stringify(form.value)}else form.value=null;error.value='';notice.value=''}
async function run(action){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e.message}finally{busy.value=false}}
async function refreshSelected(){const id=selected.value?.id;await load();const fresh=data.value?.items.find(i=>i.id===id);if(fresh){original.value=JSON.stringify(form.value);select(fresh)}else{selected.value=null;form.value=null;original.value='';resetReview()}}
async function create(){if(!guard())return;await run(async()=>{const s=sources.value[Number(sourceIndex.value)];if(!s)throw new Error('請先選擇已評分來源。');const result=await api(base,{method:'POST',body:{snapshotId:s.snapshotId,questionId:s.questionId,reportSubmissionId:s.reportSubmissionId}});original.value=JSON.stringify(form.value);await load();select(data.value.items.find(i=>i.id===result.id));notice.value='已建立私有草稿，請檢查並去識別展示內容。'})}
async function save(){await run(async()=>{await api(`${base}/${selected.value.id}`,{method:'PUT',body:{...form.value,expectedVersion:selected.value.version}});await refreshSelected();notice.value='觀摩草稿已儲存，尚未自動公開。'})}
async function upload(){await run(async()=>{if(dirty.value)throw new Error('請先儲存文字再上傳PDF副本。');const body=new FormData();body.append('file',pdf.value);body.append('expectedVersion',selected.value.version);await api(`${base}/${selected.value.id}/attachments`,{method:'POST',body});await refreshSelected();notice.value='展示PDF副本已上傳，需重新審查後發布。'})}
async function showPreview(){await run(async()=>{preview.value=await api(`${base}/${selected.value.id}/preview`,{method:'POST'});reviewed.value=true})}
async function publish(){await run(async()=>{await api(`${base}/${selected.value.id}/publish`,{method:'POST',body:{expectedVersion:selected.value.version,anonymized:anonymized.value,authorized:authorized.value,noAnswerLeak:noLeak.value,authorizationReference:authorizationRef.value}});await refreshSelected();notice.value='匿名觀摩已發布給本課同學。'})}
async function withdraw(){await run(async()=>{await api(`${base}/${selected.value.id}/withdraw`,{method:'POST',body:{expectedVersion:selected.value.version}});original.value=JSON.stringify(form.value);await refreshSelected();notice.value='觀摩已撤下，學生無法再從平台讀取。'})}
async function download(id,draft=false){await run(async()=>{const b=await api(`${base}/${id}/attachment${draft?'?draft=true':''}`,{download:true}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='showcase.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
const labels={draft:'草稿',published:'已發布',withdrawn:'已撤下'}
</script>
<template><section class="surface form-surface"><h2>優良作業觀摩</h2><p class="muted">教師選取並確認匿名展示內容，僅供本課同學參考；不公開原作者身分與私人作答歷程。</p><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<form v-if="writable" @submit.prevent="create"><label>選擇已評分作答來源<select aria-label="觀摩作答來源" v-model="sourceIndex" required :disabled="busy"><option value="">請選擇來源</option><option v-for="(s,i) in sources" :key="`${s.snapshotId||s.reportSubmissionId}-${s.questionId||''}`" :value="i">{{s.kind==='pdf'?'PDF':'申論'}} · {{s.title}} · {{s.studentName}} {{s.questionId?'· '+s.questionId.slice(0,6):''}} · {{s.canPublish?'已關閉':'尚待關閉評量'}}</option></select></label><button class="button primary" :disabled="busy||sourceIndex===''">建立觀摩草稿</button><p class="field-hint">來源名單僅教學人員可見。正式評分／成績公布後才可選，來源評量關閉且不可再作答後才可發布。</p></form>
<div v-if="data" class="showcase-list"><button v-for="item in data.items" :key="item.id" type="button" class="question-editor showcase-choice" :aria-pressed="selected?.id===item.id" @click="select(item)"><strong>{{data.staff?item.content.title:item.title}}</strong><span v-if="data.staff">{{labels[item.status]}}<span v-if="item.status==='published'&&item.draftRevision!==item.publishedRevision"> · 有未發布新草稿</span></span><span v-else>{{new Date(item.publishedAt).toLocaleDateString()}}</span></button><p v-if="!data.items.length" class="muted">{{data.staff?'尚無觀摩項目，可從已評分來源準備草稿。':'目前尚無已發布的觀摩內容。'}}</p></div></section>
<section v-if="selected&&data?.staff" class="surface form-surface"><h2>觀摩草稿與發布</h2><p class="submission-notice">請移除學生及個案可識別資訊，並確認題幹、內文、PDF封面與文件屬性。原作答與成績保持不變；平台不自動保證匿名。</p><form @submit.prevent="save"><fieldset :disabled="busy||!writable"><label>觀摩標題<input aria-label="觀摩標題" v-model="form.title" required maxlength="200" /></label><label>展示題幹／必要背景<textarea aria-label="觀摩展示背景" v-model="form.background" rows="5" maxlength="24000" /></label><label>已去識別作答<textarea aria-label="觀摩展示作答" v-model="form.answer" rows="10" maxlength="64000" /></label><label>教師教學說明<textarea aria-label="觀摩教學說明" v-model="form.notes" rows="5" maxlength="16000" /></label><button v-if="writable" class="button primary" :disabled="!dirty">儲存觀摩草稿</button></fieldset></form>
<template v-if="selected.kind==='pdf'"><form v-if="writable" @submit.prevent="upload"><label>另外上傳已去識別PDF<input aria-label="觀摩展示PDF" type="file" accept=".pdf,application/pdf" @change="pdf=$event.target.files[0]" required /></label><p class="field-hint">20MB內；須由教師另備展示副本，學生原始PDF不會直接公開。先儲存文字再上傳。</p><button class="button secondary" :disabled="busy||!pdf||dirty">上傳展示PDF</button></form><button v-if="selected.hasAttachment" class="button secondary" :disabled="busy" @click="download(selected.id,true)">下載草稿展示副本</button><p v-else class="muted">尚未上傳展示副本，不能發布PDF觀摩。</p></template>
<button class="button secondary" :disabled="busy||dirty" @click="showPreview">預覽學生呈現內容</button><p v-if="dirty" class="field-hint">請先儲存修改再預覽或發布。</p>
<form v-if="writable&&data.canPublish" @submit.prevent="publish"><fieldset :disabled="busy||dirty||!reviewed"><legend>教師發布確認（針對目前已儲存版本）</legend><label class="choice-label"><input type="checkbox" v-model="anonymized" required />已檢查學生與個案資訊並完成去識別</label><label class="choice-label"><input type="checkbox" v-model="authorized" required />已確認作答展示使用授權</label><label class="choice-label"><input type="checkbox" v-model="noLeak" required />已確認評量關閉、無再作答與洩題影響</label><label>授權依據／政策紀錄識別<input aria-label="觀摩授權依據" v-model="authorizationRef" required maxlength="500" placeholder="填紀錄識別，不貼個資或授權文件全文" /></label><button class="button primary" :disabled="!anonymized||!authorized||!noLeak||!authorizationRef.trim()">發布匿名觀摩</button></fieldset></form><p v-else-if="writable" class="field-hint">助教可準備／預覽，請由本課教師最終發布。</p>
<button v-if="selected.status!=='withdrawn'" class="button danger" :disabled="busy" @click="withdraw">撤下觀摩</button><p class="field-hint">撤下會停止後續平台存取，無法收回已下載、截圖或讀過的內容。封存課程仍允許撤下。</p></section>
<section v-if="(preview&&data?.staff)||(selected&&!data?.staff)" class="surface form-surface showcase-public"><p v-if="data.staff" class="eyebrow">學生呈現預覽（尚未發布的新版本僅教學端可見）</p><template v-for="item in [data.staff?preview:selected]" :key="item.id"><h2>{{item.title}}</h2><h3 v-if="item.background">題幹／背景</h3><p class="showcase-text">{{item.background}}</p><h3 v-if="item.answer">作答範例</h3><p class="showcase-text">{{item.answer}}</p><h3 v-if="item.notes">教師教學說明</h3><p class="showcase-text">{{item.notes}}</p><button v-if="item.hasAttachment" class="button secondary" :disabled="busy" @click="download(item.id,data.staff)">下載匿名展示PDF</button></template></section>
</template>
<style scoped>.showcase-list{display:grid;gap:12px;margin-top:24px}.showcase-choice{display:flex;justify-content:space-between;gap:16px;text-align:left;cursor:pointer;width:100%;color:inherit;background:transparent}.showcase-choice[aria-pressed=true]{border-color:#625bc4}.showcase-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9}.button{margin:8px 8px 8px 0}textarea{width:100%;box-sizing:border-box}.showcase-public h2,.showcase-choice strong{overflow-wrap:anywhere}</style>
